// before: a button that shows a count
-function CartButton({ count }: { count: number }) {
-  return <button>Cart ({count})</button>;
-}

// after: 'now it's extensible'
+const CartContext = createContext<{ count: number } | null>(null);
+function CartButton({ count, children }: { count: number; children: React.ReactNode }) {
+  return <CartContext.Provider value={{ count }}>{children}</CartContext.Provider>;
+}
+CartButton.Label = function Label() {
+  const ctx = useContext(CartContext)!;
+  return <span>Cart ({ctx.count})</span>;
+};
+// used in exactly one place, always as <CartButton count={n}><CartButton.Label/></CartButton>
